{
  "name": "@dreamorosi/agent-timekeeper-opencode",
  "version": "0.2.5",
  "description": "OpenCode plugin for Agent Timekeeper: records Sessions, Runs, tool calls, Interactions and terminal Input and Focus as Signals, and uploads them to your own endpoint",
  "type": "module",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/dreamorosi/agent-timekeeper.git",
    "directory": "packages/opencode"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "time-tracking"
  ],
  "exports": {
    ".": "./dist/server.js",
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "engines": {
    "node": ">=24"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "typecheck": "tsc",
    "bundle": "node scripts/bundle.ts",
    "fixtures": "node scripts/fixtures.ts"
  },
  "devDependencies": {
    "@agent-timekeeper/shipping": "workspace:*",
    "@agent-timekeeper/signal": "workspace:*",
    "@opencode/client": "^2.1.4",
    "@opencode/plugin": "^2.1.4",
    "@opencode/theme": "2.1.4",
    "@opentui/core": "^0.6.8",
    "@opentui/solid": "^0.6.8",
    "solid-js": "^1.9.17"
  }
}
